//
// Clipboard guard for test runs: saves the user's clipboard, puts a known multi-type sentinel
// on it, hashes every type of every item before and after each scenario, and puts the
// user's content back on every exit path (architecture 3.7: the hash must not change).
// The hash leaves out the empty `org.nspasteboard.AutoGeneratedType` marker, which 3.7 has
// every restore add so clipboard managers skip it; every other type and byte counts.

import AppKit
import CryptoKit

@MainActor
enum Clipboard {
  private static let transient = NSPasteboard.PasteboardType("org.nspasteboard.TransientType")
  private static let autoGenerated = NSPasteboard.PasteboardType(
    "org.nspasteboard.AutoGeneratedType")
  private static let sentinelType = NSPasteboard.PasteboardType("au.ibra.dict.e2e.sentinel")

  typealias Snapshot = [[(NSPasteboard.PasteboardType, Data)]]

  /// Saves the clipboard and installs the sentinel for the duration of `body`.
  static func guarded<T>(_ body: () throws -> T) rethrows -> T {
    let saved = snapshot()
    let cleanup = Cleanup.add { restore(saved) }
    defer { Cleanup.run(cleanup) }
    installSentinel()
    return try body()
  }

  static func hash() -> String { hash(of: snapshot()) }

  /// SHA-256 over every type and its data, item by item, without the empty restore marker.
  static func hash(of items: Snapshot) -> String {
    var hasher = SHA256()
    for item in items {
      hasher.update(data: Data("item".utf8))
      for (type, data) in item where !(type == autoGenerated && data.isEmpty) {
        hasher.update(data: Data(type.rawValue.utf8))
        hasher.update(data: data)
      }
    }
    return hasher.finalize().map { String(format: "%02x", $0) }.joined()
  }

  /// The types of every item, for explaining a hash change: `[a, b] [c]`.
  static func describe() -> String {
    snapshot().map { item in "[" + item.map(\.0.rawValue).joined(separator: ", ") + "]" }
      .joined(separator: " ")
  }

  static func string() -> String? { NSPasteboard.general.string(forType: .string) }

  private static func snapshot() -> Snapshot {
    (NSPasteboard.general.pasteboardItems ?? []).map { item in
      item.types.compactMap { type in item.data(forType: type).map { (type, $0) } }
    }
  }

  private static func installSentinel() {
    let item = NSPasteboardItem()
    item.setString("Dict e2e clipboard sentinel", forType: .string)
    item.setData(Data("sentinel".utf8), forType: sentinelType)
    item.setData(Data(), forType: transient)
    NSPasteboard.general.clearContents()
    NSPasteboard.general.writeObjects([item])
  }

  private static func restore(_ saved: Snapshot) {
    NSPasteboard.general.clearContents()
    let items = saved.map { types in
      let item = NSPasteboardItem()
      for (type, data) in types { item.setData(data, forType: type) }
      if !types.contains(where: { $0.0 == autoGenerated }) {
        item.setData(Data(), forType: autoGenerated)
      }
      return item
    }
    if !items.isEmpty { NSPasteboard.general.writeObjects(items) }
    say("clipboard: restored")
  }
}
